const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountIsaPoint = ee.Geometry.Point(139.4907, -20.7303);
  const townsvillePoint = ee.Geometry.Point(146.8169, -19.2588);

  // Define "regions around" as a 100 km buffer
  const mountIsaRegion = mountIsaPoint.buffer(100000); // 100 km buffer
  const townsvilleRegion = townsvillePoint.buffer(100000); // 100 km buffer

  const startDate = '2019-01-27';
  const endDate = '2019-02-11'; // Filter up to, but not including, Feb 11 to include Feb 10

  const rainfallThresholdCm = 65;
  const rainfallThresholdMm = rainfallThresholdCm * 10; // Convert cm to mm

  // 2. Data Acquisition & Check
  const gpmCollection = ee.ImageCollection('NASA/GPM_L3/IMERG_V06/HOURLY')
    .filterDate(startDate, endDate)
    .select('precipitationCal');

  const mountIsaFiltered = gpmCollection.filterBounds(mountIsaRegion);
  const townsvilleFiltered = gpmCollection.filterBounds(townsvilleRegion);

  const mountIsaSize = await mountIsaFiltered.size().getInfo();
  const townsvilleSize = await townsvilleFiltered.size().getInfo();

  console.log(`Mount Isa images found: ${mountIsaSize}`);
  console.log(`Townsville images found: ${townsvilleSize}`);

  if (mountIsaSize === 0 || townsvilleSize === 0) {
    console.log("C1");
    return;
  }

  // Sum the precipitation for the entire period for each region
  const mountIsaTotalRainfall = mountIsaFiltered.sum();
  const townsvilleTotalRainfall = townsvilleFiltered.sum();

  // Define a reasonable scale for reduction (GPM is ~10km resolution, so 10km is fine)
  const scale = 10000; // 10 km

  // Function to calculate mean rainfall for a region and handle C2/C3
  const calculateRegionRainfall = async (image, region, name) => {
    let result = null;
    let pixelCount = 0;

    try {
      // Calculate pixel count to check for C2
      const countDict = await image.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9,
        tileScale: 16 // Increase tileScale to handle larger regions
      }).getInfo();

      pixelCount = countDict ? countDict.precipitationCal : 0;
      if (pixelCount === 0) {
        console.log(`No valid pixels remaining for ${name} after processing.`);
        return { value: null, pixels: 0, status: "C2" };
      }

      // Calculate the mean rainfall
      const rainfallDict = await image.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9,
        tileScale: 16
      }).getInfo();

      result = rainfallDict ? rainfallDict.precipitationCal : null;

    } catch (e) {
      console.error(`Error calculating rainfall for ${name}: ${e}`);
      return { value: null, pixels: 0, status: "D" }; // General error
    }

    if (result === null || isNaN(result)) {
      console.log(`Calculation failure for ${name}. Result: ${result}`);
      return { value: null, pixels: pixelCount, status: "C3" };
    }

    return { value: result, pixels: pixelCount, status: "OK" };
  };

  const mountIsaRainfallResult = await calculateRegionRainfall(mountIsaTotalRainfall, mountIsaRegion, "Mount Isa");
  const townsvilleRainfallResult = await calculateRegionRainfall(townsvilleTotalRainfall, townsvilleRegion, "Townsville");

  // Check for C2/C3/D from the results
  if (mountIsaRainfallResult.status !== "OK") {
    console.log(mountIsaRainfallResult.status);
    return;
  }
  if (townsvilleRainfallResult.status !== "OK") {
    console.log(townsvilleRainfallResult.status);
    return;
  }

  const mountIsaAvgRainfallMm = mountIsaRainfallResult.value;
  const townsvilleAvgRainfallMm = townsvilleRainfallResult.value;

  const mountIsaAvgRainfallCm = mountIsaAvgRainfallMm / 10;
  const townsvilleAvgRainfallCm = townsvilleAvgRainfallMm / 10;

  console.log(`Mount Isa Avg Rainfall (cm): ${mountIsaAvgRainfallCm.toFixed(2)} (Pixels: ${mountIsaRainfallResult.pixels})`);
  console.log(`Townsville Avg Rainfall (cm): ${townsvilleAvgRainfallCm.toFixed(2)} (Pixels: ${townsvilleRainfallResult.pixels})`);

  // 5. Validation & Final Answer
  const mountIsaOverThreshold = mountIsaAvgRainfallCm > rainfallThresholdCm;
  const townsvilleOverThreshold = townsvilleAvgRainfallCm > rainfallThresholdCm;

  if (mountIsaOverThreshold && townsvilleOverThreshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
